create table if not exists public.video_projects(id uuid primary key default gen_random_uuid(),owner_id uuid, title text not null,status text not null default 'draft',current_revision int not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.video_project_revisions(project_id uuid not null references public.video_projects on delete cascade,revision int not null,schema_version int not null,spec jsonb not null,created_by uuid,created_at timestamptz not null default now(),primary key(project_id,revision));
create table if not exists public.video_assets(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.video_projects on delete cascade,revision int not null,type text not null,storage_uri text not null,checksum text,provenance jsonb not null default '{}',license_status text not null default 'unknown',created_at timestamptz not null default now(),foreign key(project_id,revision) references public.video_project_revisions);
create table if not exists public.video_narration_jobs(id uuid primary key default gen_random_uuid(),project_id uuid not null,revision int not null,provider text not null,status text not null,request jsonb not null,result jsonb,cost numeric,currency text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(project_id,revision) references public.video_project_revisions);
create table if not exists public.video_render_jobs(id uuid primary key default gen_random_uuid(),project_id uuid not null,revision int not null,provider text not null,provider_job_id text,status text not null default 'queued',progress numeric not null default 0,attempt_count int not null default 0,output_uri text,output_checksum text,provider_response jsonb,estimated_cost numeric,actual_cost numeric,currency text,approval_state text not null default 'unreviewed',failure_category text,failure_message text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(project_id,revision) references public.video_project_revisions,unique(provider,provider_job_id));
create table if not exists public.video_render_attempts(id bigint generated always as identity primary key,render_id uuid not null references public.video_render_jobs on delete cascade,attempt int not null,status text not null,error jsonb,started_at timestamptz not null default now(),finished_at timestamptz,unique(render_id,attempt));
create table if not exists public.video_provider_usage(id bigint generated always as identity primary key,provider text not null,operation text not null,project_id uuid,revision int,render_id uuid references public.video_render_jobs,usage jsonb not null default '{}',estimated_cost numeric,actual_cost numeric,currency text,provider_request_id text,created_at timestamptz not null default now());
create table if not exists public.video_webhook_events(id bigint generated always as identity primary key,provider text not null,event_id text not null,provider_job_id text,payload jsonb not null,verified boolean not null default false,processed boolean not null default false,error text,received_at timestamptz not null default now(),unique(provider,event_id));
create table if not exists public.video_validation_results(id bigint generated always as identity primary key,render_id uuid not null references public.video_render_jobs on delete cascade,passed boolean not null,checks jsonb not null,summary text not null,created_at timestamptz not null default now());
create table if not exists public.video_approval_history(id bigint generated always as identity primary key,render_id uuid not null references public.video_render_jobs on delete cascade,project_id uuid not null,revision int not null,decision text not null check(decision in('approved','rejected')),reason text,actor_id uuid,created_at timestamptz not null default now(),foreign key(project_id,revision) references public.video_project_revisions);
create table if not exists public.video_publishing_records(id uuid primary key default gen_random_uuid(),render_id uuid not null references public.video_render_jobs,status text not null default 'disabled',request jsonb,result jsonb,created_at timestamptz not null default now());
create index if not exists video_render_jobs_status_idx on public.video_render_jobs(status,created_at);create index if not exists video_assets_project_idx on public.video_assets(project_id,revision);
alter table public.video_projects enable row level security;alter table public.video_project_revisions enable row level security;alter table public.video_assets enable row level security;alter table public.video_narration_jobs enable row level security;alter table public.video_render_jobs enable row level security;alter table public.video_render_attempts enable row level security;alter table public.video_provider_usage enable row level security;alter table public.video_webhook_events enable row level security;alter table public.video_validation_results enable row level security;alter table public.video_approval_history enable row level security;alter table public.video_publishing_records enable row level security;
